def parse_courses(html, prefix):
    soup=BeautifulSoup(html,'html.parser')
    if soup.find('input',attrs={'type':'password'}): raise ValueError('Access page')
    wanted={code for code in SPEC if code.split()[0].lower()==prefix}
    observed=[]
    for block in soup.select('.courseblock'):
        heading=block.select_one('.courseblocktitle')
        spans=heading.select('.cdspacing') if heading else []
        if len(spans)<2: continue
        match=re.match(r'[A-Z]+ \d{3}',clean(spans[0].get_text(' ',strip=True)))
        if not match or match[0] not in wanted: continue
        code=match[0]; text=clean(block.get_text(' ',strip=True)); reviewed=SPEC[code]
        if hashlib.sha256(text.encode()).hexdigest()!=reviewed['digest']:
            raise ValueError('Lehigh course description changed; independent review required: '+code)
        amount=re.search(r' (\d+) Credits?$',clean(heading.get_text(' ',strip=True)))
        c=course('lehigh',code,clean(spans[1].get_text(' ',strip=True)),PID+'-courses-'+prefix,
                 'https://catalog.lehigh.edu/courselisting/'+prefix+'/',
                 credits=int(amount[1]) if amount else None,unit='semester_hours',category=reviewed['category'])
        c['description']=reviewed['description']
        if 'Prerequisites:' in text:
            c['prerequisites']=text.split('Prerequisites:',1)[1].split('Attribute/Distribution:',1)[0].strip()
        elif 'No prerequisites' in text: c['prerequisites']='No prerequisites; open to all students.'
        elif code=='WRT 003': c['prerequisites']='Enrollment limited to multilingual English speakers; prior academic writing history, placement testing and/or ICAPE director recommendation determines placement.'
        observed.append(c)
    if {c['code'] for c in observed}!=wanted: raise ValueError('Reviewed Lehigh course identities missing')
    return dict(id=PID,courses=observed)

SOURCE_PARSERS={'https://catalog.lehigh.edu/courselisting/'+prefix+'/':partial(parse_courses,prefix=prefix)
                for prefix in sorted({code.split()[0].lower() for code in SPEC})}
